/** Public entry point — the only module consumers/docs should import from. */

export { DataGridToolbar, type DataGridToolbarProps } from "./toolbar";
export { DataGridSearch, type DataGridSearchProps } from "./search";
export { DataGridFilterMenu, type DataGridFilterMenuProps } from "./filter-menu";
export { DataGridColumnsMenu, type DataGridColumnsMenuProps } from "./columns-menu";
export { operatorsForColumnType, operatorLabel, operatorHasValue } from "./operators-for-column-type";

import type { ReactNode } from "react";
import { cn } from "@/lib/utils";
import { useDataGridInstanceId, GRID_ATTR } from "@/registry/default/components/data-grid/data-grid-sdk";

/** Props for {@link DataGridToolbar}. */
export type DataGridToolbarProps = {
  className?: string;
  children?: ReactNode;
};

/**
 * Flex frame for the grid's toolbar slots (search, filter menu, columns menu, custom buttons).
 * Consumers place it above `<DataGridRoot>`, inside the same `<DataGridProvider>`, so its children
 * share the grid's store.
 */
export function DataGridToolbar(props: DataGridToolbarProps): ReactNode {
  const { className, children } = props;
  const instanceId = useDataGridInstanceId();
  return (
    <div
      {...{ [GRID_ATTR.instance]: instanceId }}
      data-grid-toolbar=""
      className={cn("flex items-center gap-2 overflow-x-auto border-b border-border bg-background px-2 py-1.5", className)}
    >
      {children}
    </div>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type ChangeEvent,
  type KeyboardEvent as ReactKeyboardEvent,
  type ReactNode,
} from "react";
import { ChevronDown, ChevronUp, Search } from "lucide-react";
import { cn } from "@/lib/utils";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import {
  useDataGridActions,
  useDataGridLabels,
  useDataGridScrollToCellAt,
  useDataGridSearchText,
  useDataGridVisibleColumns,
} from "@/registry/default/components/data-grid/data-grid";
import {
  useDataGridInstanceId,
  GRID_ATTR,
  useDataGridSearchCapped,
  useDataGridSearchMatches,
} from "@/registry/default/components/data-grid/data-grid-sdk";

/** Default debounce (ms) between typing and updating the store's `searchText`. */
const SEARCH_DEBOUNCE_MS = 200;

/** Props for {@link DataGridSearch}. */
export type DataGridSearchProps = {
  className?: string;
  placeholder?: string;
  /**
   * Debounce (ms) between typing and the store's `searchText` update; default 200.
   */
  debounceMs?: number;
  /**
   * "Feels native" bridge: mod+F (Ctrl+F / Cmd+F) with focus inside this grid or its
   * toolbar focuses/selects this input instead of opening the browser's find bar. Native
   * find-in-page can't work over virtualized rows (only the window's rendered rows exist in the
   * DOM), and our search already scrolls to matches — this makes mod+F reach for it directly.
   * Default `true` — when this component is mounted and focus is inside this grid, mod+F
   * unambiguously means "search this grid"; with several grids on one page, mod+F always reaches
   * the grid that holds focus, never a sibling grid's search. The listener is grid-scoped (never
   * window/document globally): focus anywhere else on the page is completely untouched, so a page's own search UI
   * or the browser's native find behave exactly as if this prop didn't exist. Pass `false` to
   * disable and always defer to the browser's native find.
   */
  captureFindShortcut?: boolean;
};

/** True when `target` sits in this grid's DOM, or in a `[data-grid-toolbar]` that holds `input`; never in a sibling grid. */
function isInsideGridScope(target: EventTarget | null, instanceId: string, input: HTMLElement | null): boolean {
  if (!(target instanceof Element)) return false;
  if (target.closest(`[${GRID_ATTR.instance}="${instanceId}"]`) !== null) return true;
  const toolbar = target.closest(`[${GRID_ATTR.toolbar}]`);
  return toolbar !== null && input !== null && toolbar.contains(input);
}

/**
 * Quick-search input: debounced write to the store's `searchText`, a match-count badge
 * ("3/17"), and prev/next controls that step through matches in row-major order, moving the
 * active cell to the match and scrolling it into view. Enter/Shift+Enter mirror the buttons;
 * Escape clears the field and the store's search text.
 */
export function DataGridSearch(props: DataGridSearchProps): ReactNode {
  const { className, placeholder, captureFindShortcut = true, debounceMs = SEARCH_DEBOUNCE_MS } = props;
  const labels = useDataGridLabels();
  const actions = useDataGridActions();
  const searchText = useDataGridSearchText();
  const matches = useDataGridSearchMatches();
  const capped = useDataGridSearchCapped();
  const visibleColumns = useDataGridVisibleColumns();
  const scrollToCell = useDataGridScrollToCellAt();
  const instanceId = useDataGridInstanceId();

  // local input value decoupled from the store's debounced searchText, so typing never stalls.
  const [inputValue, setInputValue] = useState(searchText);
  const [matchIndex, setMatchIndex] = useState(0);
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const inputRef = useRef<HTMLInputElement | null>(null);

  // an external clear (e.g. filter reset) should resync the visible input text.
  useEffect(() => {
    setInputValue(searchText);
  }, [searchText]);

  // restart navigation at the first hit during render, not in an effect: a shrinking list must not paint an out-of-range index
  const [lastMatches, setLastMatches] = useState(matches);
  if (lastMatches !== matches) {
    setLastMatches(matches);
    setMatchIndex(0);
  }

  useEffect(() => () => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
  }, []);

  // No DOM ancestor spans toolbar and root, so listen on document and gate by instance id or the toolbar holding this input.
  useEffect(() => {
    if (!captureFindShortcut) return;

    function onKeyDown(event: KeyboardEvent) {
      const isFind = (event.metaKey || event.ctrlKey) && !event.altKey && event.key.toLowerCase() === "f";
      if (!isFind || !isInsideGridScope(event.target, instanceId, inputRef.current)) return;
      event.preventDefault();
      const input = inputRef.current;
      if (!input) return;
      if (document.activeElement === input) {
        input.select();
      } else {
        input.focus();
      }
    }

    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [captureFindShortcut, instanceId]);

  const commitSearch = useCallback(
    (value: string) => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
      debounceRef.current = setTimeout(() => actions.setSearch(value), debounceMs);
    },
    [actions, debounceMs],
  );

  const goToMatch = useCallback(
    (index: number) => {
      if (matches.length === 0) return;
      const wrapped = ((index % matches.length) + matches.length) % matches.length;
      setMatchIndex(wrapped);
      const match = matches[wrapped]!; // wrapped is modulo'd into [0, matches.length)
      const col = visibleColumns.findIndex((c) => c.id === match.columnId);
      if (col === -1) return;
      const coord = { col, row: match.row };
      actions.setActiveCellAt(coord);
      scrollToCell(coord);
    },
    [actions, scrollToCell, matches, visibleColumns],
  );

  const onChange = useCallback(
    (event: ChangeEvent<HTMLInputElement>) => {
      setInputValue(event.target.value);
      commitSearch(event.target.value);
    },
    [commitSearch],
  );

  const clear = useCallback(() => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    setInputValue("");
    actions.setSearch("");
  }, [actions]);

  const onKeyDown = useCallback(
    (event: ReactKeyboardEvent<HTMLInputElement>) => {
      if (event.key === "Escape") {
        event.preventDefault();
        clear();
      } else if (event.key === "Enter") {
        event.preventDefault();
        goToMatch(matchIndex + (event.shiftKey ? -1 : 1));
      }
    },
    [clear, goToMatch, matchIndex],
  );

  const hasMatches = matches.length > 0;

  return (
    <div data-grid-search="" className={cn("flex h-8 items-center gap-1", className)}>
      <div className="relative">
        <Search className="pointer-events-none absolute inset-s-2 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground" />
        <Input
          ref={inputRef}
          value={inputValue}
          onChange={onChange}
          onKeyDown={onKeyDown}
          placeholder={placeholder ?? labels.toolbar.searchPlaceholder}
          aria-label={labels.toolbar.searchAriaLabel}
          className="h-8 w-56 ps-7"
        />
      </div>
      {searchText.trim() !== "" && (
        <span
          data-grid-search-count=""
          role="status"
          aria-live="polite"
          className="min-w-fit shrink-0 text-xs tabular-nums text-muted-foreground"
        >
          {hasMatches
            ? capped
              ? labels.toolbar.searchMatchesCapped(matchIndex + 1)
              : labels.toolbar.searchMatches(matchIndex + 1, matches.length)
            : labels.toolbar.searchNoMatches}
        </span>
      )}
      <Button
        type="button"
        variant="ghost"
        size="icon-sm"
        aria-label={labels.toolbar.searchPreviousMatch}
        disabled={!hasMatches}
        onClick={() => goToMatch(matchIndex - 1)}
      >
        <ChevronUp />
      </Button>
      <Button
        type="button"
        variant="ghost"
        size="icon-sm"
        aria-label={labels.toolbar.searchNextMatch}
        disabled={!hasMatches}
        onClick={() => goToMatch(matchIndex + 1)}
      >
        <ChevronDown />
      </Button>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState, type KeyboardEvent as ReactKeyboardEvent, type ReactNode } from "react";
import { AutoScroller } from "@dnd-kit/dom";
import { DragDropProvider } from "@dnd-kit/react";
import { useSortable } from "@dnd-kit/react/sortable";
import { Filter, GripVertical, Trash2 } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import {
  useDataGridActions,
  useDataGridAllColumns,
  useDataGridCellTypes,
  useDataGridFilterState,
  useDataGridJoinOperator,
  useDataGridLabels,
  useDataGridVisibleColumns,
  type AnyColumnDef,
  type DataGridLabels,
  type FilterJoinOperator,
  type FilterOperator,
  type FilterSpec,
} from "@/registry/default/components/data-grid/data-grid";
import { columnLabelText, isDev, operatorsForColumnType, resolveFilterOperators } from "@/registry/default/components/data-grid/data-grid-sdk";
import { emptyValueFor, operatorHasValue, operatorLabel } from "./operators-for-column-type";
import { DataGridFilterValueInput } from "./filter-value-input";

/** Props for {@link DataGridFilterMenu}. */
export type DataGridFilterMenuProps = {
  className?: string;
  /**
   * Source the column options from every column (including hidden ones) instead of only the visible
   * columns; default false. Without it, a filter set on a hidden column (programmatically or via a
   * restored layout) keeps applying but renders with no column context and logs a dev-time warning.
   */
  allColumns?: boolean;
  /**
   * Replaces the operator list the menu offers per column. Resolution order: this prop (a returned
   * `undefined` falls through), then the column's own `filterOperators`, then the built-in
   * `operatorsForColumnType` for its `type`.
   */
  operatorsForColumn?: (column: AnyColumnDef) => readonly FilterOperator[] | undefined;
};

/** dnd-kit drag payload for a filter row: compiler-checked in place of `Record<string, any>`. */
type FilterRowDragData = { index: number; filterId: string };

/** Moves the item at `fromIndex` to `toIndex`, returning a new array (no mutation of `list`). */
function moveItem<T>(list: T[], fromIndex: number, toIndex: number): T[] {
  const next = list.slice();
  const [moved] = next.splice(fromIndex, 1);
  if (moved === undefined) return list;
  next.splice(toIndex, 0, moved);
  return next;
}

/**
 * Popover listing active filters as one aligned grid row per filter — anatomy ported from tablecn's
 * `DataTableFilterList` (a join cell: "Where" on row 1, an And/Or select on row 2, static join text
 * on rows 3+; field select; operator select; typed value input; trash icon-button; drag handle drag
 * handle; footer "Add filter"/"Reset filters" buttons) but built from this repo's own Base UI
 * components/conventions rather than transliterated from tablecn's Radix markup. Reordering uses
 * `@dnd-kit/react`'s sortable primitives (handle-initiated pointer drag with a lifted-row overlay
 * feel via `isDragSource`), plus a plain ArrowUp/ArrowDown-on-drag handle fallback that always wins over
 * the library's own keyboard sensor (see {@link FilterRow}'s `onKeyDown`). Rows are keyed by
 * `FilterSpec.filterId` (stable identity independent of array position) since multiple filter rows
 * on the same column are allowed and meaningful; row order is array order in `FilterSpec[]`,
 * persisted through `setFilters` on every reorder.
 */
export function DataGridFilterMenu(props: DataGridFilterMenuProps): ReactNode {
  const { className, allColumns = false, operatorsForColumn } = props;
  const actions = useDataGridActions();
  const filters = useDataGridFilterState();
  const joinOperator = useDataGridJoinOperator();
  const visibleColumns = useDataGridVisibleColumns();
  const gridColumns = useDataGridAllColumns();
  const columns = allColumns ? gridColumns : visibleColumns;
  const labels = useDataGridLabels();
  const cellTypes = useDataGridCellTypes();
  const filterableColumns = columns.filter((c) => c.filterable !== false);

  // per-column operator list: this prop > the column's filterOperators > the cell type's declared operators > the name-based type default
  const operatorsFor = useCallback(
    (column: AnyColumnDef | undefined): readonly FilterOperator[] => {
      if (!column) return operatorsForColumnType(undefined);
      return operatorsForColumn?.(column) ?? resolveFilterOperators(column, column.type ? cellTypes[column.type] : undefined);
    },
    [operatorsForColumn, cellTypes],
  );

  // A filter on a column outside the menu's option list (a hidden column by default, or one no
  // longer in the grid) still applies to the view but renders with no column context and no picker
  // entry to re-target it — warn in dev and point at the fix.
  useEffect(() => {
    if (!isDev()) return;
    const listed = new Set(columns.map((c) => c.id));
    const orphans = filters.filter((f) => !listed.has(f.columnId));
    if (orphans.length === 0) return;
    const ids = Array.from(new Set(orphans.map((f) => f.columnId)));
    console.warn(
      `[data-grid-toolbar] DataGridFilterMenu: ${orphans.length} filter row(s) target column(s) missing from the menu's column list (${ids.join(", ")}); pass allColumns to manage hidden-column filters here`,
    );
  }, [filters, columns]);

  const [announcement, setAnnouncement] = useState("");
  const gripRefs = useRef(new Map<string, HTMLButtonElement | null>());
  const addButtonRef = useRef<HTMLButtonElement>(null);
  const pendingFocusFilterIdRef = useRef<string | null>(null);

  // ponytail: lock root scroll during a drag - at drag end the browser re-focuses the drag handle and natively re-centers it in the viewport, jumping the page
  const rootScrollLockRef = useRef<(() => void) | null>(null);
  const lockRootScroll = useCallback(() => {
    if (rootScrollLockRef.current) return;
    const y = window.scrollY;
    const onScroll = () => {
      if (window.scrollY !== y) window.scrollTo(0, y);
    };
    document.addEventListener("scroll", onScroll, true);
    rootScrollLockRef.current = () => {
      document.removeEventListener("scroll", onScroll, true);
      rootScrollLockRef.current = null;
    };
  }, []);
  const unlockRootScroll = useCallback(() => rootScrollLockRef.current?.(), []);

  useEffect(() => {
    const pendingId = pendingFocusFilterIdRef.current;
    if (!pendingId) return;
    pendingFocusFilterIdRef.current = null;
    gripRefs.current.get(pendingId)?.focus({ preventScroll: true });
  }, [filters]);

  useEffect(() => unlockRootScroll, [unlockRootScroll]);

  const updateFilter = useCallback(
    (filterId: string | undefined, next: Partial<FilterSpec>) => {
      actions.setFilters(filters.map((f) => (f.filterId === filterId ? { ...f, ...next } : f)));
    },
    [actions, filters],
  );

  const removeFilter = useCallback(
    (filterId: string | undefined, index: number) => {
      actions.setFilters(filters.filter((f) => f.filterId !== filterId));
      // focus follows deletion: the next row's drag handle, or the Add button once the list empties.
      const nextFocusId = filters[index + 1]?.filterId ?? filters[index - 1]?.filterId;
      if (nextFocusId) pendingFocusFilterIdRef.current = nextFocusId;
      else requestAnimationFrame(() => addButtonRef.current?.focus({ preventScroll: true }));
    },
    [actions, filters],
  );

  const addFilter = useCallback(() => {
    const first = filterableColumns[0];
    if (!first) return;
    const operator = operatorsFor(first)[0]!; // always non-empty (TEXT_OPERATORS is the floor)
    actions.setFilters([...filters, { columnId: first.id, operator, value: emptyValueFor(operator) }]);
  }, [actions, filterableColumns, filters, operatorsFor]);

  const resetFilters = useCallback(() => {
    actions.setFilters([]);
    actions.setJoinOperator("and");
  }, [actions]);

  const announceMove = useCallback(
    (filterId: string, toIndex: number, total: number) => {
      const filter = filters.find((f) => f.filterId === filterId);
      const column = columns.find((c) => c.id === filter?.columnId);
      const label = column ? columnLabelText(column) : (filter?.columnId ?? "");
      setAnnouncement(labels.toolbar.filterReorderAnnouncement(label, toIndex + 1, total));
    },
    [filters, columns, labels],
  );

  const reorderFilters = useCallback(
    (fromIndex: number, toIndex: number, filterId: string) => {
      if (fromIndex === toIndex) return;
      const next = moveItem(filters, fromIndex, toIndex);
      actions.setFilters(next);
      pendingFocusFilterIdRef.current = filterId;
      announceMove(filterId, toIndex, next.length);
    },
    [actions, filters, announceMove],
  );

  return (
    <Popover>
      <PopoverTrigger
        render={
          <Button type="button" variant="outline" size="sm" className={cn("relative", className)} aria-label={labels.toolbar.filterAriaLabel}>
            <Filter />
            {labels.toolbar.filter}
            {filters.length > 0 && (
              <Badge data-grid-filter-count="" variant="secondary" className="ms-1">
                {filters.length}
              </Badge>
            )}
          </Button>
        }
      />
      <PopoverContent align="start" className="flex w-full min-w-105 flex-col gap-3.5 p-4">
        <div data-grid-filter-menu="" className="flex flex-col gap-3.5">
          <h4 className="font-medium leading-none text-muted-foreground">{labels.toolbar.filter}</h4>
          {filters.length === 0 && <p className="text-sm text-muted-foreground">{labels.toolbar.noFiltersApplied}</p>}
          <div aria-live="polite" role="status" className="sr-only">
            {announcement}
          </div>
          {filters.length > 0 && (
            <DragDropProvider<FilterRowDragData>
              // ponytail: drop AutoScroller — the popover portals to body, so the page is a scrollable
              // ancestor and dragging near a viewport edge scrolls the page; re-add it if the list
              // (max-h-75) overflows often enough that mid-drag auto-scrolling is needed
              plugins={(defaults) => defaults.filter((p) => p !== AutoScroller)}
              onDragStart={lockRootScroll}
              onDragEnd={(event) => {
                unlockRootScroll();
                if (event.canceled) return;
                const sourceData = event.operation.source?.data;
                const targetData = event.operation.target?.data;
                const fromIndex = sourceData?.index;
                const toIndex = targetData?.index;
                const filterId = sourceData?.filterId;
                if (fromIndex === undefined || toIndex === undefined || !filterId) return;
                reorderFilters(fromIndex, toIndex, filterId);
              }}
            >
              <div role="list" className="flex max-h-75 flex-col gap-2 overflow-y-auto p-1">
                {filters.map((filter, index) => {
                  const column = columns.find((c) => c.id === filter.columnId);
                  return (
                    <FilterRow
                      key={filter.filterId}
                      filter={filter}
                      index={index}
                      total={filters.length}
                      column={column}
                      joinOperator={joinOperator}
                      columns={columns}
                      filterableColumns={filterableColumns}
                      operatorsFor={operatorsFor}
                      labels={labels}
                      onJoinOperatorChange={actions.setJoinOperator}
                      onUpdate={updateFilter}
                      onRemove={removeFilter}
                      onArrowReorder={(toIndex) => reorderFilters(index, toIndex, filter.filterId!)}
                      gripRef={(el) => {
                        gripRefs.current.set(filter.filterId!, el);
                      }}
                    />
                  );
                })}
              </div>
            </DragDropProvider>
          )}
          <div className="flex w-full items-center gap-2">
            <Button type="button" ref={addButtonRef} onClick={addFilter} disabled={filterableColumns.length === 0}>
              {labels.toolbar.addFilter}
            </Button>
            {filters.length > 0 && (
              <Button type="button" variant="outline" onClick={resetFilters}>
                {labels.toolbar.clearFilters}
              </Button>
            )}
          </div>
        </div>
      </PopoverContent>
    </Popover>
  );
}

type FilterRowProps = {
  filter: FilterSpec;
  index: number;
  total: number;
  column: AnyColumnDef | undefined;
  joinOperator: FilterJoinOperator;
  columns: readonly AnyColumnDef[];
  filterableColumns: readonly AnyColumnDef[];
  operatorsFor: (column: AnyColumnDef | undefined) => readonly FilterOperator[];
  labels: DataGridLabels;
  onJoinOperatorChange: (value: FilterJoinOperator) => void;
  onUpdate: (filterId: string | undefined, next: Partial<FilterSpec>) => void;
  onRemove: (filterId: string | undefined, index: number) => void;
  onArrowReorder: (toIndex: number) => void;
  gripRef: (el: HTMLButtonElement | null) => void;
};

/** One filter row: `useSortable` wires pointer-drag reorder via `@dnd-kit/react`; the drag handle's `onKeyDown` implements the ArrowUp/ArrowDown fallback, which always takes precedence over dnd-kit's own keyboard sensor (checked first, `stopPropagation`'d). */
function FilterRow(props: FilterRowProps): ReactNode {
  const { filter, index, total, column, joinOperator, columns, filterableColumns, operatorsFor, labels, onJoinOperatorChange, onUpdate, onRemove, onArrowReorder, gripRef } = props;
  const operators = operatorsFor(column);
  const joinOperatorItems = [
    { value: "and", label: labels.toolbar.joinOperatorAnd },
    { value: "or", label: labels.toolbar.joinOperatorOr },
  ];
  const columnItems = filterableColumns.map((c) => ({ value: c.id, label: columnLabelText(c) }));
  const operatorItems = operators.map((op) => ({ value: op, label: operatorLabel(op, labels.filterOperators) }));
  // No plugins: dnd-kit's optimistic DOM moves fight React's re-render after a drop; `onGripKeyDown` is the keyboard path.
  const { ref, handleRef, isDragSource } = useSortable<FilterRowDragData>({
    id: filter.filterId!,
    index,
    data: { index, filterId: filter.filterId! }, // filterId always assigned by the store; see FilterSpec
    plugins: [],
  });

  const onGripKeyDown = useCallback(
    (event: ReactKeyboardEvent<HTMLButtonElement>) => {
      if (event.key === "Backspace" || event.key === "Delete") {
        event.preventDefault();
        event.stopPropagation(); // wins over dnd-kit's keyboard sensor regardless of library support
        onRemove(filter.filterId, index);
        return;
      }
      if (event.key !== "ArrowUp" && event.key !== "ArrowDown") return;
      event.preventDefault();
      event.stopPropagation(); // wins over dnd-kit's keyboard sensor regardless of library support
      const target = index + (event.key === "ArrowUp" ? -1 : 1);
      if (target < 0 || target >= total) return;
      onArrowReorder(target);
    },
    [filter.filterId, index, total, onArrowReorder, onRemove],
  );

  return (
    <div
      ref={ref}
      data-grid-filter-row=""
      role="listitem"
      className={cn(
        "grid grid-cols-[minmax(4.5rem,auto)_minmax(0,1fr)_minmax(0,1fr)_minmax(0,1.5fr)_auto_auto] items-center gap-1.5 transition-transform",
        isDragSource && "z-10 scale-[1.01] opacity-90 shadow-lg",
      )}
    >
      <div className="min-w-18 text-center">
        {index === 0 ? (
          <span className="text-sm text-muted-foreground">{labels.toolbar.filterWhere}</span>
        ) : index === 1 ? (
          <Select
            items={joinOperatorItems}
            value={joinOperator}
            onValueChange={(value) => {
              if (value === null) return;
              onJoinOperatorChange(value as FilterJoinOperator);
            }}
          >
            <SelectTrigger className="h-8 w-full" aria-label={labels.toolbar.joinOperatorAriaLabel}>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="and">{labels.toolbar.joinOperatorAnd}</SelectItem>
              <SelectItem value="or">{labels.toolbar.joinOperatorOr}</SelectItem>
            </SelectContent>
          </Select>
        ) : (
          <span className="text-sm text-muted-foreground">{joinOperator === "or" ? labels.toolbar.joinOperatorOr : labels.toolbar.joinOperatorAnd}</span>
        )}
      </div>
      <Select
        items={columnItems}
        value={filter.columnId}
        onValueChange={(value) => {
          if (value === null) return;
          const nextColumn = columns.find((c) => c.id === value);
          const nextOperators = operatorsFor(nextColumn);
          const nextOperator = nextOperators.includes(filter.operator) ? filter.operator : nextOperators[0];
          onUpdate(filter.filterId, { columnId: value, operator: nextOperator, value: emptyValueFor(nextOperator) });
        }}
      >
        <SelectTrigger className="h-8 w-full" aria-label={labels.toolbar.filterColumnAriaLabel}>
          <SelectValue className="truncate" />
        </SelectTrigger>
        <SelectContent>
          {filterableColumns.map((c) => (
            <SelectItem key={c.id} value={c.id}>
              {columnLabelText(c)}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      <Select
        items={operatorItems}
        value={filter.operator}
        onValueChange={(value) => {
          if (value === null) return;
          const nextOperator = value as FilterOperator;
          // each operator family has its own value shape; reset rather than carry a mismatched one
          onUpdate(filter.filterId, { operator: nextOperator, value: emptyValueFor(nextOperator) });
        }}
      >
        <SelectTrigger className="h-8 w-full" aria-label={labels.toolbar.filterOperatorAriaLabel}>
          <SelectValue className="truncate" />
        </SelectTrigger>
        <SelectContent>
          {operators.map((op) => (
            <SelectItem key={op} value={op}>
              {operatorLabel(op, labels.filterOperators)}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      <div className="min-w-0">
        {operatorHasValue(filter.operator) ? (
          <DataGridFilterValueInput column={column} operator={filter.operator} value={filter.value} onValueChange={(value) => onUpdate(filter.filterId, { value })} />
        ) : (
          <div className="h-8 w-full rounded border bg-transparent" />
        )}
      </div>
      <Button type="button" variant="outline" size="icon" className="size-8 shrink-0" aria-label={labels.toolbar.removeFilterAriaLabel} onClick={() => onRemove(filter.filterId, index)}>
        <Trash2 />
      </Button>
      <Button
        type="button"
        variant="outline"
        size="icon"
        ref={(el) => {
          handleRef(el);
          gripRef(el);
        }}
        className={cn("size-8 shrink-0 cursor-grab touch-none", isDragSource && "cursor-grabbing")}
        aria-label={labels.toolbar.reorderFilterAriaLabel}
        // prevent native mousedown focus: Chromium re-centers the focused drag handle in the viewport mid-drag and the page jumps
        onMouseDown={(e) => e.preventDefault()}
        onKeyDown={onGripKeyDown}
      >
        <GripVertical />
      </Button>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState, type ChangeEvent, type ReactNode } from "react";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import {
  useDataGridCellTypes,
  useDataGridLabels,
  type AnyColumnDef,
  type FilterOperator,
  type GridCellTypes,
} from "@/registry/default/components/data-grid/data-grid";
import { resolveFilterValueInput } from "@/registry/default/components/data-grid/data-grid-sdk";
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Button } from "@/components/ui/button";
import { operatorIsAnyOf, operatorIsBetween } from "./operators-for-column-type";

/** Debounce (ms) between typing and committing a filter value. */
const FILTER_VALUE_DEBOUNCE_MS = 200;

/** Props for {@link DataGridFilterValueInput}. */
export type DataGridFilterValueInputProps = {
  /** The filtered column; its cell type's `filter.valueInput` (or the type-name default) picks the widget. */
  column: AnyColumnDef | undefined;
  operator: FilterOperator;
  value: string | [string, string] | string[] | undefined;
  onValueChange: (value: string | [string, string] | string[]) => void;
};

/** Debounces a single text/number/date input's keystrokes into one commit. */
function useDebouncedInput(value: string, onValueChange: (value: string) => void) {
  const [inputValue, setInputValue] = useState(value);
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // an external change (e.g. clear all, column swap) should resync the visible text.
  useEffect(() => {
    setInputValue(value);
  }, [value]);

  useEffect(() => () => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
  }, []);

  const onChange = useCallback(
    (event: ChangeEvent<HTMLInputElement>) => {
      const next = event.target.value;
      setInputValue(next);
      if (debounceRef.current) clearTimeout(debounceRef.current);
      debounceRef.current = setTimeout(() => onValueChange(next), FILTER_VALUE_DEBOUNCE_MS);
    },
    [onValueChange],
  );

  return { inputValue, onChange };
}

/** A single debounced text/number/date value input, shared by the plain and `isBetween` (two-input) layouts. */
function SingleValueInput(props: {
  type: "text" | "number" | "date";
  value: string;
  onValueChange: (value: string) => void;
  ariaLabel: string;
  placeholder?: string;
}) {
  const { type, value, onValueChange, ariaLabel, placeholder } = props;
  const { inputValue, onChange } = useDebouncedInput(value, onValueChange);
  return (
    <Input
      type={type}
      value={inputValue}
      onChange={onChange}
      placeholder={placeholder}
      aria-label={ariaLabel}
      className="h-8 w-full"
    />
  );
}

/**
 * The `isBetween` two-input range layout. Each side debounces independently (same as a lone value
 * input), but both commits read the OTHER side's value from a ref at commit time rather than closing
 * over the render-time value — two edits within the same debounce window (e.g. filling "from" then
 * "to" quickly) would otherwise race: whichever debounce fires last overwrites the other's edit with
 * the stale value it captured 200ms earlier.
 */
function BetweenValueInput(props: {
  type: "text" | "number" | "date";
  from: string;
  to: string;
  onValueChange: (value: [string, string]) => void;
  fromAriaLabel: string;
  toAriaLabel: string;
}) {
  const { type, from, to, onValueChange, fromAriaLabel, toAriaLabel } = props;
  const fromRef = useRef(from);
  const toRef = useRef(to);
  fromRef.current = from;
  toRef.current = to;

  const commitFrom = useCallback((next: string) => onValueChange([next, toRef.current]), [onValueChange]);
  const commitTo = useCallback((next: string) => onValueChange([fromRef.current, next]), [onValueChange]);

  const fromInput = useDebouncedInput(from, commitFrom);
  const toInput = useDebouncedInput(to, commitTo);

  return (
    <div className="flex items-center gap-1.5">
      <Input type={type} value={fromInput.inputValue} onChange={fromInput.onChange} aria-label={fromAriaLabel} className="h-8 w-full" />
      <Input type={type} value={toInput.inputValue} onChange={toInput.onChange} aria-label={toAriaLabel} className="h-8 w-full" />
    </div>
  );
}

/**
 * The `isAnyOf` multi-choice input: a dropdown of the select column's own `choices`, each a
 * checkbox. Commits immediately (no debounce — a click is already a deliberate, discrete choice,
 * unlike a keystroke).
 */
function AnyOfValueInput(props: {
  choices: readonly { value: string; label: string }[];
  selected: readonly string[];
  onValueChange: (value: string[]) => void;
  ariaLabel: string;
  summary: string;
}) {
  const { choices, selected, onValueChange, ariaLabel, summary } = props;
  const toggle = (choice: string, checked: boolean) => {
    // rebuild from `choices` so the committed order is the column's own, not click order
    const next = new Set(selected);
    if (checked) next.add(choice);
    else next.delete(choice);
    onValueChange(choices.map((c) => c.value).filter((v) => next.has(v)));
  };

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button type="button" variant="outline" className="h-8 w-full justify-start font-normal" aria-label={ariaLabel}>
            <span className="truncate">{summary}</span>
          </Button>
        }
      />
      <DropdownMenuContent align="start">
        {choices.map((choice) => (
          <DropdownMenuCheckboxItem
            key={choice.value}
            checked={selected.includes(choice.value)}
            onCheckedChange={(checked) => toggle(choice.value, checked)}
          >
            {choice.label}
          </DropdownMenuCheckboxItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/**
 * Filter-row value input: renders the widget the filtered column's cell type declares in
 * `filter.valueInput` (a number, date, true/false, choices, or text input, or the type's own
 * component), with a type-name default, and debounces text/number/date keystrokes so typing never
 * triggers a `setFilters` view-index rebuild per character. `isBetween` renders two of the
 * column's typed input side by side instead of one.
 */
export function DataGridFilterValueInput(props: DataGridFilterValueInputProps): ReactNode {
  const { column, operator, value, onValueChange } = props;
  const labels = useDataGridLabels();
  const cellTypes = useDataGridCellTypes();
  const valueInput = column ? resolveFilterValueInput(column, column.type ? cellTypes[column.type] : undefined) : "text";

  if (typeof valueInput !== "string" && column) {
    const CustomInput = valueInput;
    return <CustomInput column={column} operator={operator} value={value} onValueChange={onValueChange} />;
  }
  const inputType = valueInput === "number" ? "number" : valueInput === "date" ? "date" : "text";

  if (operatorIsAnyOf(operator)) {
    const choices = (column?.options as GridCellTypes["select"]["options"] | undefined)?.choices ?? [];
    const selected = Array.isArray(value) ? value : [];
    return (
      <AnyOfValueInput
        choices={choices}
        selected={selected}
        onValueChange={onValueChange}
        ariaLabel={labels.toolbar.filterValueAriaLabel}
        summary={labels.toolbar.filterValueAnyOfSummary(selected.length)}
      />
    );
  }

  if (operatorIsBetween(operator)) {
    const [from = "", to = ""] = Array.isArray(value) ? value : ["", ""];
    return (
      <BetweenValueInput
        type={inputType}
        from={from}
        to={to}
        onValueChange={onValueChange}
        fromAriaLabel={labels.toolbar.filterValueFromAriaLabel}
        toAriaLabel={labels.toolbar.filterValueToAriaLabel}
      />
    );
  }

  const textValue = typeof value === "string" ? value : "";

  if (valueInput === "boolean") {
    const booleanItems = [
      { value: "true", label: labels.toolbar.filterValueTrue },
      { value: "false", label: labels.toolbar.filterValueFalse },
    ];
    return (
      <Select items={booleanItems} value={textValue || null} onValueChange={(next) => onValueChange(next ?? "")}>
        <SelectTrigger className="h-8 w-full" aria-label={labels.toolbar.filterValueAriaLabel}>
          <SelectValue placeholder={labels.toolbar.filterValuePlaceholder} />
        </SelectTrigger>
        <SelectContent>
          {booleanItems.map((item) => (
            <SelectItem key={item.value} value={item.value}>
              {item.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    );
  }

  if (valueInput === "choices") {
    const choices = (column?.options as GridCellTypes["select"]["options"] | undefined)?.choices ?? [];
    return (
      <Select items={choices} value={textValue || null} onValueChange={(next) => onValueChange(next ?? "")}>
        <SelectTrigger className="h-8 w-full" aria-label={labels.toolbar.filterValueAriaLabel}>
          <SelectValue placeholder={labels.toolbar.filterValuePlaceholder} />
        </SelectTrigger>
        <SelectContent>
          {choices.map((choice) => (
            <SelectItem key={choice.value} value={choice.value}>
              {choice.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    );
  }

  return (
    <SingleValueInput
      type={inputType}
      value={textValue}
      onValueChange={onValueChange}
      ariaLabel={labels.toolbar.filterValueAriaLabel}
      placeholder={labels.toolbar.filterValuePlaceholder}
    />
  );
}

